inline const FSG *GetFSG(const void *buf) {
  return ::flatbuffers::GetRoot<FSG>(buf);
}

inline const FSG *GetSizePrefixedFSG(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<FSG>(buf);
}

inline const char *FSGIdentifier() {
  return "$FSG";
}

inline bool FSGBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FSGIdentifier());
}

inline bool SizePrefixedFSGBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FSGIdentifier(), true);
}

template <bool B = false>
inline bool VerifyFSGBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<FSG>(FSGIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedFSGBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<FSG>(FSGIdentifier());
}

inline void FinishFSGBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<FSG> root) {
  fbb.Finish(root, FSGIdentifier());
}

inline void FinishSizePrefixedFSGBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<FSG> root) {
  fbb.FinishSizePrefixed(root, FSGIdentifier());
}

inline std::unique_ptr<FSGT> UnPackFSG(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<FSGT>(GetFSG(buf)->UnPack(res));
}

inline std::unique_ptr<FSGT> UnPackSizePrefixedFSG(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<FSGT>(GetSizePrefixedFSG(buf)->UnPack(res));
}

